package vn.svframe.svframelib.api.crafting.ingredients; import vn.svframe.svframelib.api.crafting.uimanager.ProvidedUIFilter; import java.util.*; public class SVFrameRecipeIngredient { private final SVFrameIngredient ingredient; public SVFrameRecipeIngredient(SVFrameIngredient i){ingredient=Objects.requireNonNull(i);} public SVFrameRecipeIngredient(ProvidedUIFilter f){if(f==null)throw new IllegalArgumentException("filter");ingredient=new SVFrameIngredient(f.toString(),f);} public SVFrameIngredient getIngredient(){return ingredient;} }
